module.exports = "<!DOCTYPE html>\n<html lang=\"ar\" dir=\"rtl\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<title>𝕻𝖍𝖆𝖓𝖙𝖔𝖒𝖘 | بوابة عائلة فانتومز - سيرفر كيان رول بلاي</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=Cairo:wght@400;600;700;800;900&family=Changa:wght@700;800&family=Cinzel:wght@700;900&display=swap\" rel=\"stylesheet\">\n<link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css\">\n<style>\n:root {\n  /* Rich Dark Brown & Amber Bronze Luxury Gang Theme */\n  --bg-deep: #0c0704;\n  --bg-main: #130b06;\n  --bg-card: #1b1009;\n  --bg-card-hover: #26170d;\n  --bg-card-light: #2c1a0f;\n  \n  --brown-border: #3d2414;\n  --brown-border-light: #57331b;\n  --bronze-glow: rgba(217, 146, 67, 0.28);\n  --bronze-glow-strong: rgba(217, 146, 67, 0.55);\n  \n  --amber: #d99243;\n  --amber-light: #f3c283;\n  --amber-dark: #91541c;\n  --caramel: #b86e28;\n  \n  --tx: #fbf5ee;\n  --tx-muted: #baa38f;\n  --tx-dim: #826c59;\n  \n  --red: #c0392b;\n  --green: #27ae60;\n  \n  --font-title: 'Changa', 'Cairo', sans-serif;\n  --font-english: 'Cinzel', serif;\n  --radius: 18px;\n  color-scheme: dark;\n}\n\n*, *::before, *::after { box-sizing: border-box; }\nhtml { scroll-behavior: smooth; scroll-padding-top: 85px; }\nbody {\n  margin: 0;\n  background: var(--bg-deep);\n  background-image: \n    radial-gradient(ellipse at 50% 0%, rgba(217, 146, 67, 0.14) 0%, transparent 60%),\n    radial-gradient(circle at 100% 30%, rgba(145, 84, 28, 0.12) 0%, transparent 50%),\n    radial-gradient(circle at 0% 80%, rgba(61, 36, 20, 0.25) 0%, transparent 60%),\n    linear-gradient(to bottom, #0e0805, #080402);\n  color: var(--tx);\n  font-family: 'Cairo', Tahoma, sans-serif;\n  line-height: 1.7;\n  overflow-x: hidden;\n  min-height: 100vh;\n}\n\na { color: inherit; text-decoration: none; }\n.wrap { max-width: 1140px; margin: auto; padding: 0 24px; }\n\n/* Navigation */\nnav {\n  position: sticky;\n  top: 0;\n  z-index: 100;\n  background: rgba(14, 8, 5, 0.92);\n  backdrop-filter: blur(18px);\n  -webkit-backdrop-filter: blur(18px);\n  border-bottom: 1px solid var(--brown-border);\n}\nnav .wrap {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  height: 75px;\n  gap: 16px;\n}\n.brand {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n  font-family: var(--font-english);\n  font-weight: 900;\n  font-size: 23px;\n  letter-spacing: 2px;\n  color: var(--amber-light);\n}\n.brand img {\n  width: 42px;\n  height: 42px;\n  border-radius: 50%;\n  border: 2px solid var(--amber);\n  box-shadow: 0 0 15px var(--bronze-glow);\n}\n.nav-links {\n  display: flex;\n  align-items: center;\n  gap: 22px;\n  color: var(--tx-muted);\n  font-weight: 700;\n  font-size: 15px;\n}\n.nav-links a { transition: .2s; }\n.nav-links a:hover { color: var(--amber-light); }\n.nav-actions { display: flex; align-items: center; gap: 12px; }\n\n/* Buttons */\n.btn {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  gap: 10px;\n  border: 0;\n  cursor: pointer;\n  font-family: inherit;\n  font-weight: 800;\n  padding: 11px 24px;\n  border-radius: 13px;\n  background: linear-gradient(135deg, var(--amber), var(--caramel));\n  color: #120904;\n  box-shadow: 0 6px 22px var(--bronze-glow);\n  transition: all .25s ease;\n  font-size: 15px;\n}\n.btn:hover {\n  transform: translateY(-2px);\n  box-shadow: 0 10px 28px var(--bronze-glow-strong);\n  filter: brightness(1.1);\n  color: #0b0502;\n}\n.btn.ghost {\n  background: rgba(44, 26, 15, 0.4);\n  border: 1px solid var(--brown-border-light);\n  color: var(--tx);\n  box-shadow: none;\n}\n.btn.ghost:hover {\n  background: rgba(217, 146, 67, 0.15);\n  border-color: var(--amber);\n  color: var(--amber-light);\n}\n.btn.sm { padding: 6px 14px; font-size: 13px; border-radius: 9px; }\n.btn.del { background: #691e17; color: #fff; box-shadow: none; }\n.btn.del:hover { background: #88251c; }\n.btn.dc {\n  background: #5865F2;\n  color: #fff;\n  box-shadow: 0 6px 20px rgba(88, 101, 242, 0.35);\n}\n.btn.dc:hover { background: #4752c4; box-shadow: 0 8px 24px rgba(88, 101, 242, 0.5); }\n\n/* User Pill */\n.user-pill {\n  display: none;\n  align-items: center;\n  gap: 10px;\n  background: var(--bg-card);\n  border: 1px solid var(--brown-border);\n  padding: 5px 12px 5px 6px;\n  border-radius: 99px;\n  font-weight: 700;\n}\n.user-pill img, .user-pill .default-av {\n  width: 34px;\n  height: 34px;\n  border-radius: 50%;\n  object-fit: cover;\n  border: 2px solid var(--amber);\n}\n.default-av {\n  display: grid;\n  place-items: center;\n  background: linear-gradient(135deg, var(--amber), var(--caramel));\n  color: #120904;\n  font-weight: 900;\n  font-size: 15px;\n}\n.user-rank-chip {\n  font-size: 12px;\n  padding: 3px 11px;\n  border-radius: 99px;\n  background: rgba(217, 146, 67, 0.15);\n  color: var(--amber-light);\n  border: 1px solid var(--brown-border-light);\n}\n\n/* Hero Section */\n.hero {\n  position: relative;\n  text-align: center;\n  padding: 95px 0 75px;\n  overflow: hidden;\n}\n.hero::before {\n  content: \"\";\n  position: absolute;\n  top: -15%;\n  left: 50%;\n  transform: translateX(-50%);\n  width: 750px;\n  height: 480px;\n  background: radial-gradient(ellipse at 50% 40%, var(--bronze-glow), transparent 70%);\n  z-index: -1;\n  pointer-events: none;\n}\n.hero-crest {\n  width: 140px;\n  height: 140px;\n  margin: 0 auto 20px;\n  border-radius: 50%;\n  border: 3px solid var(--amber);\n  box-shadow: 0 0 40px var(--bronze-glow-strong);\n  animation: float 4s ease-in-out infinite;\n  object-fit: cover;\n}\n@keyframes float {\n  0%, 100% { transform: translateY(0); }\n  50% { transform: translateY(-8px); }\n}\n.city-tag {\n  display: inline-flex;\n  align-items: center;\n  gap: 8px;\n  border: 1px solid var(--brown-border-light);\n  border-radius: 99px;\n  padding: 6px 20px;\n  color: var(--amber-light);\n  font-size: 14px;\n  font-weight: 800;\n  background: rgba(27, 16, 9, 0.85);\n  box-shadow: 0 4px 18px rgba(0,0,0,0.5);\n}\n.city-tag .dot { width: 9px; height: 9px; border-radius: 50%; background: #2ecc71; box-shadow: 0 0 10px #2ecc71; }\nh1.hero-title {\n  font-family: var(--font-title);\n  font-size: clamp(48px, 9vw, 92px);\n  margin: 20px 0 10px;\n  font-weight: 900;\n  letter-spacing: 2px;\n  line-height: 1.15;\n  background: linear-gradient(135deg, #ffffff 15%, var(--amber-light) 50%, var(--amber) 85%);\n  -webkit-background-clip: text;\n  background-clip: text;\n  color: transparent;\n  filter: drop-shadow(0 4px 25px rgba(217, 146, 67, 0.35));\n}\n.hero-desc {\n  color: var(--tx-muted);\n  max-width: 680px;\n  margin: 0 auto 34px;\n  font-size: 19px;\n  line-height: 1.8;\n}\n.hero-cta { display: flex; justify-content: center; gap: 14px; flex-wrap: wrap; margin-bottom: 50px; }\n\n/* Stats Bar */\n.stats-bar {\n  display: grid;\n  grid-template-columns: repeat(4, 1fr);\n  gap: 16px;\n  background: var(--bg-card);\n  border: 1px solid var(--brown-border);\n  border-radius: var(--radius);\n  padding: 24px;\n  margin-top: 30px;\n  box-shadow: 0 10px 30px rgba(0,0,0,0.5);\n}\n.stat-box { text-align: center; border-left: 1px solid var(--brown-border); }\n.stat-box:last-child { border-left: 0; }\n.stat-box .num {\n  font-family: var(--font-title);\n  font-size: 34px;\n  font-weight: 800;\n  color: var(--amber-light);\n  line-height: 1.2;\n}\n.stat-box .label { font-size: 14px; color: var(--tx-muted); margin-top: 4px; font-weight: 600; }\n\n/* Section Headers */\nsection { padding: 80px 0; border-bottom: 1px solid rgba(61, 36, 20, 0.4); }\n.sec-hd { text-align: center; margin-bottom: 48px; }\n.sec-hd h2 {\n  font-family: var(--font-title);\n  font-size: 38px;\n  margin: 0 0 10px;\n  font-weight: 800;\n}\n.sec-hd h2 i { font-style: normal; color: var(--amber); }\n.sec-hd p { color: var(--tx-muted); font-size: 16px; margin: 0; }\n\n/* Cards & Grids */\n.grid { display: grid; gap: 20px; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); }\n.card {\n  background: var(--bg-card);\n  border: 1px solid var(--brown-border);\n  border-radius: var(--radius);\n  padding: 26px;\n  transition: all .25s ease;\n  position: relative;\n  overflow: hidden;\n}\n.card:hover {\n  border-color: var(--amber);\n  background: var(--bg-card-hover);\n  transform: translateY(-3px);\n  box-shadow: 0 14px 40px var(--bronze-glow);\n}\n\n/* About Section */\n.about-box {\n  display: grid;\n  grid-template-columns: 1.4fr 1fr;\n  gap: 32px;\n  align-items: center;\n}\n.about-text {\n  font-size: 18px;\n  color: #dfcdbd;\n  white-space: pre-line;\n  line-height: 1.9;\n}\n.boss-card {\n  text-align: center;\n  padding: 38px 24px;\n  background: linear-gradient(145deg, #24160d, #190e07);\n  border: 1px solid var(--brown-border-light);\n}\n.boss-av-wrap {\n  position: relative;\n  width: 105px;\n  height: 105px;\n  margin: 0 auto 18px;\n}\n.boss-av {\n  width: 100%;\n  height: 100%;\n  border-radius: 50%;\n  object-fit: cover;\n  border: 3px solid var(--amber);\n  box-shadow: 0 0 25px var(--bronze-glow-strong);\n}\n.boss-title { font-size: 14px; color: var(--amber-light); font-weight: 800; letter-spacing: 1px; }\n\n/* Rules Section */\n.rule-card {\n  display: flex;\n  gap: 18px;\n  align-items: flex-start;\n}\n.rule-num {\n  flex-shrink: 0;\n  width: 44px;\n  height: 44px;\n  border-radius: 12px;\n  background: rgba(217, 146, 67, 0.14);\n  border: 1px solid var(--brown-border-light);\n  color: var(--amber);\n  display: grid;\n  place-items: center;\n  font-weight: 900;\n  font-size: 20px;\n  font-family: var(--font-title);\n}\n.rule-body h3 { margin: 0 0 8px; font-size: 18px; color: #fff; }\n.rule-body p { margin: 0; color: var(--tx-muted); font-size: 15px; line-height: 1.7; }\n\n/* Ranks Section */\n.rank-card { border-top: 3px solid var(--brown-border); }\n.rank-card.top-rank {\n  border-top-color: var(--amber);\n  background: linear-gradient(180deg, rgba(217,146,67,0.08), var(--bg-card));\n}\n.rank-hd {\n  display: flex;\n  align-items: center;\n  gap: 14px;\n  margin-bottom: 14px;\n}\n.rank-badge {\n  width: 44px;\n  height: 44px;\n  border-radius: 12px;\n  display: grid;\n  place-items: center;\n  font-weight: 900;\n  font-size: 18px;\n  background: var(--bg-deep);\n  border: 1px solid var(--brown-border);\n  color: var(--amber);\n}\n.rank-card.top-rank .rank-badge {\n  background: linear-gradient(135deg, var(--amber), var(--caramel));\n  color: #120904;\n  border: 0;\n}\n.rank-title { margin: 0; font-size: 20px; font-weight: 800; }\n.rank-sub { margin: 2px 0 0; color: var(--tx-muted); font-size: 13px; }\n.members-chips { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 12px; }\n.member-chip {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  background: rgba(255, 255, 255, 0.04);\n  border: 1px solid var(--brown-border);\n  padding: 4px 12px;\n  border-radius: 99px;\n  font-size: 13px;\n  font-weight: 600;\n}\n.member-chip img { width: 18px; height: 18px; border-radius: 50%; }\n\n/* Creators Section */\n.creator-card { text-align: center; padding: 32px 20px; }\n.creator-av {\n  width: 78px;\n  height: 78px;\n  border-radius: 50%;\n  margin: 0 auto 14px;\n  object-fit: cover;\n  border: 2px solid var(--amber);\n  box-shadow: 0 0 20px var(--bronze-glow);\n}\n.creator-plat {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  font-size: 13px;\n  padding: 4px 14px;\n  border-radius: 99px;\n  margin-top: 8px;\n  font-weight: 700;\n}\n.plat-twitch { background: rgba(145, 70, 255, 0.2); color: #cbb3f7; border: 1px solid #9146ff; }\n.plat-youtube { background: rgba(255, 0, 0, 0.15); color: #ff9191; border: 1px solid #ff0000; }\n.plat-kick { background: rgba(83, 252, 24, 0.15); color: #87f859; border: 1px solid #53fc18; }\n.plat-tiktok { background: rgba(254, 44, 85, 0.15); color: #ff8fa5; border: 1px solid #fe2c55; }\n\n/* Rivalries Section CSS */\n.rivalry-card {\n  border-top: 3px solid var(--brown-border);\n  transition: transform .2s, border-color .2s;\n  display: flex;\n  flex-direction: column;\n  justify-content: space-between;\n}\n.rivalry-card:hover {\n  transform: translateY(-3px);\n  border-color: var(--amber);\n}\n.rivalry-header {\n  display: flex;\n  align-items: center;\n  gap: 14px;\n  margin-bottom: 12px;\n}\n.rivalry-logo {\n  width: 52px;\n  height: 52px;\n  border-radius: 12px;\n  background: var(--bg-card-2);\n  border: 1px solid var(--brown-border);\n  object-fit: cover;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  font-size: 22px;\n  color: var(--amber);\n  flex-shrink: 0;\n}\n.rivalry-badge {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  padding: 4px 10px;\n  border-radius: 99px;\n  font-size: 12px;\n  font-weight: 700;\n}\n.badge-war {\n  background: rgba(220, 38, 38, 0.2);\n  color: #f87171;\n  border: 1px solid rgba(220, 38, 38, 0.4);\n}\n.badge-skirmish {\n  background: rgba(245, 158, 11, 0.2);\n  color: #fbbf24;\n  border: 1px solid rgba(245, 158, 11, 0.4);\n}\n.badge-truce {\n  background: rgba(16, 185, 129, 0.2);\n  color: #34d399;\n  border: 1px solid rgba(16, 185, 129, 0.4);\n}\n.badge-crushed {\n  background: rgba(107, 114, 128, 0.2);\n  color: #9ca3af;\n  border: 1px solid rgba(107, 114, 128, 0.4);\n}\n\n/* Discord Server Showcase Card */\n.dc-showcase {\n  background: linear-gradient(145deg, #1f130b, #150c07);\n  border: 1px solid var(--brown-border-light);\n  border-radius: var(--radius);\n  padding: 30px;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 20px;\n  flex-wrap: wrap;\n  margin-top: 40px;\n}\n.dc-showcase-left { display: flex; align-items: center; gap: 18px; }\n.dc-showcase-icon {\n  width: 64px;\n  height: 64px;\n  border-radius: 50%;\n  border: 2px solid var(--amber);\n  box-shadow: 0 0 20px var(--bronze-glow);\n}\n\n/* Application Section */\n.app-container { max-width: 840px; margin: 0 auto; }\n.app-status-box {\n  background: var(--bg-card);\n  border: 1px solid var(--brown-border-light);\n  border-radius: var(--radius);\n  padding: 30px;\n  text-align: center;\n  margin-bottom: 30px;\n}\n.app-status-badge {\n  display: inline-block;\n  padding: 6px 20px;\n  border-radius: 99px;\n  font-weight: 800;\n  font-size: 15px;\n  margin-bottom: 12px;\n}\n.status-pending { background: rgba(241, 196, 15, 0.2); color: #f1c40f; border: 1px solid #f1c40f; }\n.status-accepted { background: rgba(46, 204, 113, 0.2); color: #2ecc71; border: 1px solid #2ecc71; }\n.status-rejected { background: rgba(231, 76, 60, 0.2); color: #e74c3c; border: 1px solid #e74c3c; }\n\n.app-form {\n  background: var(--bg-card);\n  border: 1px solid var(--brown-border);\n  border-radius: var(--radius);\n  padding: 36px;\n  box-shadow: 0 10px 40px rgba(0,0,0,0.5);\n}\n.form-grid-2 { display: grid; grid-template-columns: 1fr 1fr; gap: 18px; }\n.form-group { margin-bottom: 20px; }\n.form-group label {\n  display: block;\n  font-size: 14px;\n  font-weight: 700;\n  color: var(--amber-light);\n  margin-bottom: 8px;\n}\n.form-group label small { color: var(--tx-muted); font-weight: 400; font-size: 12px; }\n.form-control {\n  width: 100%;\n  font-family: inherit;\n  font-size: 15px;\n  color: var(--tx);\n  background: #0f0905;\n  border: 1px solid var(--brown-border);\n  border-radius: 10px;\n  padding: 12px 14px;\n  transition: .2s;\n}\n.form-control:focus {\n  outline: none;\n  border-color: var(--amber);\n  box-shadow: 0 0 12px var(--bronze-glow);\n}\ntextarea.form-control { resize: vertical; min-height: 90px; }\n\n/* Admin Panel */\n#panel { display: none; }\n.panel-tabs {\n  display: flex;\n  gap: 10px;\n  border-bottom: 1px solid var(--brown-border);\n  padding-bottom: 12px;\n  margin-bottom: 25px;\n  overflow-x: auto;\n}\n.tab-btn {\n  background: transparent;\n  border: 1px solid var(--brown-border);\n  color: var(--tx-muted);\n  padding: 10px 20px;\n  border-radius: 10px;\n  font-family: inherit;\n  font-weight: 700;\n  font-size: 14px;\n  cursor: pointer;\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  transition: .2s;\n}\n.tab-btn.active, .tab-btn:hover {\n  background: rgba(217,146,67,0.15);\n  border-color: var(--amber);\n  color: var(--amber-light);\n}\n.tab-pane { display: none; }\n.tab-pane.active { display: block; }\n\n.review-item {\n  background: #140c07;\n  border: 1px solid var(--brown-border);\n  border-radius: 14px;\n  padding: 20px;\n  margin-bottom: 18px;\n}\n.review-item.accepted { border-color: rgba(46,204,113,0.4); }\n.review-item.rejected { border-color: rgba(231,76,60,0.3); opacity: 0.8; }\n.review-hd {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  flex-wrap: wrap;\n  gap: 12px;\n  border-bottom: 1px solid var(--brown-border);\n  padding-bottom: 12px;\n  margin-bottom: 14px;\n}\n.review-meta {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));\n  gap: 12px;\n  font-size: 14px;\n  margin-bottom: 16px;\n  background: rgba(0,0,0,0.25);\n  padding: 12px;\n  border-radius: 8px;\n}\n.review-answer {\n  background: rgba(255,255,255,0.02);\n  padding: 10px 14px;\n  border-radius: 8px;\n  margin-bottom: 10px;\n  font-size: 14px;\n}\n.review-answer b { color: var(--amber-light); display: block; margin-bottom: 4px; }\n.review-actions {\n  display: flex;\n  gap: 10px;\n  align-items: center;\n  flex-wrap: wrap;\n  margin-top: 14px;\n  padding-top: 12px;\n  border-top: 1px solid var(--brown-border);\n}\n\n/* Modal */\n.modal-overlay {\n  position: fixed;\n  inset: 0;\n  background: rgba(0,0,0,0.8);\n  display: none;\n  place-items: center;\n  z-index: 200;\n  padding: 20px;\n}\n.modal-overlay.active { display: grid; }\n.modal-content {\n  background: var(--bg-card);\n  border: 1px solid var(--brown-border-light);\n  border-radius: 20px;\n  padding: 30px;\n  max-width: 500px;\n  width: 100%;\n}\n\n/* Toast */\n#toast {\n  position: fixed;\n  bottom: 24px;\n  right: 24px;\n  z-index: 300;\n  background: #1e120a;\n  border: 1px solid var(--amber);\n  color: var(--tx);\n  padding: 12px 24px;\n  border-radius: 12px;\n  box-shadow: 0 10px 30px rgba(0,0,0,0.85);\n  font-weight: 700;\n  display: none;\n  animation: slideIn .3s ease;\n}\n@keyframes slideIn {\n  from { transform: translateY(20px); opacity: 0; }\n  to { transform: translateY(0); opacity: 1; }\n}\n\n/* Footer */\nfooter {\n  border-top: 1px solid var(--brown-border);\n  background: #090503;\n  text-align: center;\n  color: var(--tx-muted);\n  padding: 45px 20px;\n  font-size: 14px;\n}\n.footer-links { display: flex; justify-content: center; gap: 22px; margin-bottom: 18px; font-weight: 700; }\n.footer-links a:hover { color: var(--amber-light); }\n\n@media(max-width: 820px) {\n  .nav-links { display: none; }\n  .stats-bar { grid-template-columns: repeat(2, 1fr); gap: 20px; }\n  .stat-box { border: 0; }\n  .about-box { grid-template-columns: 1fr; }\n  .form-grid-2 { grid-template-columns: 1fr; }\n  .dc-showcase { text-align: center; justify-content: center; }\n  .dc-showcase-left { flex-direction: column; }\n}\n</style>\n</head>\n<body>\n\n<!-- Navigation -->\n<nav>\n  <div class=\"wrap\">\n    <a class=\"brand\" href=\"#top\">\n      <img src=\"https://cdn.discordapp.com/icons/1525115353003327578/160270721afdfc2b180499e5469288a6.png\" alt=\"Phantoms Logo\">\n      𝕻𝖍𝖆𝖓𝖙𝖔𝖒𝖘\n    </a>\n\n    <div class=\"nav-links\">\n      <a href=\"#about\">عن العائلة</a>\n      <a href=\"#rules\">القوانين</a>\n      <a href=\"#ranks\">الرتب</a>\n      <a href=\"#rivalries\">العداوات والحروب ⚔️</a>\n      <a href=\"#creators\">صناع المحتوى</a>\n      <a href=\"#apply\" id=\"applyNavBtn\">التقديم بالعائلة</a>\n      <a href=\"#panel\" id=\"panelNavBtn\" style=\"display:none; color: var(--amber);\">لوحة التحكم</a>\n    </div>\n\n    <div class=\"nav-actions\">\n      <a class=\"btn dc sm\" href=\"https://discord.gg/5Pa2GNGUS\" target=\"_blank\">\n        <i class=\"fa-brands fa-discord\"></i> سيرفر الديسكورد\n      </a>\n      <a class=\"btn\" id=\"loginBtn\" href=\"/api/login\">\n        <i class=\"fa-solid fa-right-to-bracket\"></i> دخول ديسكورد\n      </a>\n      <a class=\"btn ghost sm\" id=\"bossQuickBtn\" href=\"/api/login/boss\" title=\"دخول مباشر كـ Boss (VOLT)\" style=\"border-color:var(--amber); color:var(--amber);\">\n        👑 دخول Boss\n      </a>\n      <div class=\"user-pill\" id=\"userPill\">\n        <div id=\"uavWrap\"></div>\n        <span id=\"uName\"></span>\n        <span class=\"user-rank-chip\" id=\"uRank\"></span>\n        <a class=\"btn ghost sm\" href=\"javascript:void(0)\" onclick=\"logoutUser()\" title=\"تسجيل الخروج\"><i class=\"fa-solid fa-power-off\"></i></a>\n      </div>\n    </div>\n  </div>\n</nav>\n\n<!-- Hero Section -->\n<header class=\"hero\" id=\"top\">\n  <div class=\"wrap\">\n    <img class=\"hero-crest\" src=\"https://cdn.discordapp.com/icons/1525115353003327578/160270721afdfc2b180499e5469288a6.png\" alt=\"شعار فانتومز\">\n    \n    <div>\n      <div class=\"city-tag\">\n        <span class=\"dot\"></span>\n        <span id=\"serverBadge\">سيرفر كيان رول بلاي · [KYN] · FiveM</span>\n      </div>\n    </div>\n\n    <h1 class=\"hero-title\">عائلة فانتومز</h1>\n    <p class=\"hero-desc\" id=\"heroTagline\">عيلة مش زي أي عيلة. ولاء، قوة، وأسلوب ماشي بخطة تحت قيادة VOLT.</p>\n\n    <div class=\"hero-cta\">\n      <a class=\"btn\" href=\"#apply\"><i class=\"fa-solid fa-file-pen\"></i> قدّم الآن للانضمام</a>\n      <a class=\"btn dc\" id=\"dcInviteLink\" href=\"https://discord.gg/5Pa2GNGUS\" target=\"_blank\"><i class=\"fa-brands fa-discord\"></i> انضم لسيرفر الديسكورد</a>\n      <a class=\"btn ghost\" href=\"#rules\"><i class=\"fa-solid fa-scale-balanced\"></i> قوانين العائلة</a>\n    </div>\n\n    <!-- Stats Bar -->\n    <div class=\"stats-bar\">\n      <div class=\"stat-box\">\n        <div class=\"num\" id=\"statMembersCount\">85+</div>\n        <div class=\"label\">عضو في الديسكورد</div>\n      </div>\n      <div class=\"stat-box\">\n        <div class=\"num\">9</div>\n        <div class=\"label\">رتب قيادية وتنظيمية</div>\n      </div>\n      <div class=\"stat-box\">\n        <div class=\"num\" id=\"statRivalriesCount\">2</div>\n        <div class=\"label\">النزاعات والحروب</div>\n      </div>\n      <div class=\"stat-box\">\n        <div class=\"num\" id=\"statCreatorsCount\">3</div>\n        <div class=\"label\">صناع محتوى وبثوث</div>\n      </div>\n      <div class=\"stat-box\">\n        <div class=\"num\">100%</div>\n        <div class=\"label\">ولاء للقيادة</div>\n      </div>\n    </div>\n  </div>\n</header>\n\n<!-- About Section -->\n<section id=\"about\">\n  <div class=\"wrap\">\n    <div class=\"sec-hd\">\n      <h2>عن <i>فانتومز</i></h2>\n      <p>تاريخ العائلة، المبادئ، والهدف في مدينة كيان</p>\n    </div>\n\n    <div class=\"about-box\">\n      <div class=\"about-text\" id=\"aboutContent\">\n        فانتومز (PHANTOMS) هي إحدى أعرق وأقوى العائلات في سيرفر كيان رول بلاي [KYN]. تأسست العائلة على مبادئ ثابتة: الذكاء والتخطيط والولاء الأخوي قبل السلاح. نتحكم في سيناريوهات المدينة باحترافية وهيبة تُحترم من الجميع، ونسعى دائماً لبناء مجتمع رول بلاي نظيف ومترابط.\n      </div>\n      <div class=\"card boss-card\">\n        <div class=\"boss-av-wrap\">\n          <img class=\"boss-av\" id=\"bossAv\" src=\"https://cdn.discordapp.com/icons/1525115353003327578/160270721afdfc2b180499e5469288a6.png\" alt=\"VOLT\">\n        </div>\n        <h3 id=\"bossName\" style=\"font-size: 24px; margin: 0 0 4px;\">VOLT</h3>\n        <div class=\"boss-title\">THE BOSS · مؤسس وزعيم العائلة</div>\n        <p style=\"color: var(--tx-muted); font-size: 14px; margin-top: 10px;\">\n          \"الهيبة مش بكثرة السلاح، الهيبة برجالة ضهر بعض في أي وقت وأي ظرف.\"\n        </p>\n      </div>\n    </div>\n\n    <!-- Discord Community Showcase Card -->\n    <div class=\"dc-showcase\">\n      <div class=\"dc-showcase-left\">\n        <img class=\"dc-showcase-icon\" src=\"https://cdn.discordapp.com/icons/1525115353003327578/160270721afdfc2b180499e5469288a6.png\" alt=\"Phantoms Discord\">\n        <div>\n          <h3 style=\"margin:0 0 4px; font-size:20px;\">سيرفر ديسكورد عائلة 𝕻𝖍𝖆𝖓𝖙𝖔𝖒𝖘</h3>\n          <div style=\"color:var(--tx-muted); font-size:14px;\">انضم لأكثر من 85 عضواً في مجتمع فانتومز الرسمي في كيان رول بلاي</div>\n        </div>\n      </div>\n      <a class=\"btn dc\" href=\"https://discord.gg/5Pa2GNGUS\" target=\"_blank\">\n        <i class=\"fa-brands fa-discord\"></i> دخول السيرفر الآن\n      </a>\n    </div>\n  </div>\n</section>\n\n<!-- Rules Section -->\n<section id=\"rules\">\n  <div class=\"wrap\">\n    <div class=\"sec-hd\">\n      <h2>قوانين <i>العائلة</i></h2>\n      <p>بنود صارمة وخطوط حمراء لا تقبل التهاون</p>\n    </div>\n\n    <div class=\"grid\" id=\"rulesGrid\"></div>\n  </div>\n</section>\n\n<!-- Ranks Section -->\n<section id=\"ranks\">\n  <div class=\"wrap\">\n    <div class=\"sec-hd\">\n      <h2>رتب <i>الهيكل التنظيمي</i></h2>\n      <p>تسلسل القيادة من القمة للأعضاء</p>\n    </div>\n\n    <div class=\"grid\" id=\"ranksGrid\"></div>\n  </div>\n</section>\n\n<!-- Rivalries & Current Wars Section -->\n<section id=\"rivalries\">\n  <div class=\"wrap\">\n    <div class=\"sec-hd\">\n      <h2>سجل <i>العداوات والحروب الحالية</i> ⚔️</h2>\n      <p>بيان رسمي بالعصابات المعادية، حالة النزاع في سيرفر كيان، وقواعد الاشتباك</p>\n    </div>\n\n    <div class=\"grid\" id=\"rivalriesGrid\"></div>\n  </div>\n</section>\n\n<!-- Creators & Live Streams Section -->\n<section id=\"creators\">\n  <div class=\"wrap\">\n    <div class=\"sec-hd\">\n      <h2>صناع <i>المحتوى والستريمرز</i></h2>\n      <p>شاشات وبثوث عائلة فانتومز على مختلف المنصات</p>\n    </div>\n\n    <div class=\"grid\" id=\"creatorsGrid\"></div>\n  </div>\n</section>\n\n<!-- Application / Recruitment Section -->\n<section id=\"apply\">\n  <div class=\"wrap app-container\">\n    <div class=\"sec-hd\">\n      <h2>التقديم في <i>العائلة</i></h2>\n      <p>هل تمتلك المهارة والولاء لتكون أحد أعضاء فانتومز؟</p>\n    </div>\n\n    <!-- Application Status for logged-in user -->\n    <div id=\"appStatusBox\" style=\"display: none;\"></div>\n\n    <!-- Application Form -->\n    <div class=\"app-form\" id=\"appFormBox\">\n      <div id=\"discordLoginPrompt\" style=\"display: none; text-align: center; padding: 20px;\">\n        <i class=\"fa-brands fa-discord\" style=\"font-size: 52px; color: #5865F2; margin-bottom: 14px;\"></i>\n        <h3 style=\"margin: 0 0 10px;\">تسجيل الدخول بالديسكورد مطلوب للتقديم</h3>\n        <p style=\"color: var(--tx-muted); max-width: 500px; margin: 0 auto 20px;\">\n          لضمان مصداقية التقديم وربط حسابك برولات العائلة في سيرفر الديسكورد، يرجى تسجيل الدخول بحساب ديسكورد أولاً.\n        </p>\n        <div style=\"display:flex; justify-content:center; gap:12px; flex-wrap:wrap;\">\n          <a class=\"btn dc\" href=\"/api/login\"><i class=\"fa-brands fa-discord\"></i> تسجيل الدخول بحساب ديسكورد</a>\n          <a class=\"btn ghost\" href=\"https://discord.gg/5Pa2GNGUS\" target=\"_blank\"><i class=\"fa-solid fa-users\"></i> سيرفر الديسكورد</a>\n        </div>\n      </div>\n\n      <form id=\"applyForm\" onsubmit=\"submitApplication(event)\">\n        <h3 style=\"margin-top:0; border-bottom: 1px solid var(--brown-border); padding-bottom: 12px; color: var(--amber-light);\">\n          <i class=\"fa-solid fa-id-card\"></i> بيانات المتقدم\n        </h3>\n\n        <div class=\"form-grid-2\">\n          <div class=\"form-group\">\n            <label>حساب الديسكورد</label>\n            <input class=\"form-control\" id=\"fDiscordTag\" readonly disabled style=\"opacity: 0.8; cursor: not-allowed;\">\n          </div>\n          <div class=\"form-group\">\n            <label>Discord ID</label>\n            <input class=\"form-control\" id=\"fDiscordId\" readonly disabled style=\"opacity: 0.8; cursor: not-allowed;\">\n          </div>\n        </div>\n\n        <div class=\"form-grid-2\">\n          <div class=\"form-group\">\n            <label>الاسم الواقعي *</label>\n            <input class=\"form-control\" id=\"fRealName\" required placeholder=\"مثال: بدر\">\n          </div>\n          <div class=\"form-group\">\n            <label>العمر الواقعي *</label>\n            <input class=\"form-control\" type=\"number\" id=\"fRealAge\" required min=\"15\" max=\"60\" placeholder=\"مثال: 20\">\n          </div>\n        </div>\n\n        <div class=\"form-grid-2\">\n          <div class=\"form-group\">\n            <label>اسم الشخصية داخل الرول بلاي (IC Name) *</label>\n            <input class=\"form-control\" id=\"fCharName\" required placeholder=\"مثال: Marcus Vance\">\n          </div>\n          <div class=\"form-group\">\n            <label>عمر الشخصية في اللعبة *</label>\n            <input class=\"form-control\" type=\"number\" id=\"fCharAge\" required min=\"18\" max=\"70\" placeholder=\"مثال: 27\">\n          </div>\n        </div>\n\n        <div class=\"form-grid-2\">\n          <div class=\"form-group\">\n            <label>ساعات اللعب في FiveM *</label>\n            <input class=\"form-control\" id=\"fHours\" required placeholder=\"مثال: +1200 ساعة\">\n          </div>\n          <div class=\"form-group\">\n            <label>التخصص المفضل في العائلة *</label>\n            <select class=\"form-control\" id=\"fSpecialty\" required>\n              <option value=\"شوتر ومقاتل ميداني (Shooter)\">شوتر ومقاتل ميداني (Shooter)</option>\n              <option value=\"سائق هروب ومطاردات (Driver)\">سائق هروب ومطاردات (Driver)</option>\n              <option value=\"مفاوض ودبلوماسي (Negotiator)\">مفاوض ودبلوماسي (Negotiator)</option>\n              <option value=\"استراتيجي وتخطيط عمليات (Strategist)\">استراتيجي وتخطيط عمليات (Strategist)</option>\n              <option value=\"هاكر ودعم لوجستي (Tech / Support)\">هاكر ودعم لوجستي (Tech / Support)</option>\n              <option value=\"مسعف ميداني (Medic)\">مسعف ميداني (Medic)</option>\n            </select>\n          </div>\n        </div>\n\n        <div class=\"form-group\">\n          <label>الخبرات السابقة في الرول بلاي والعصابات *</label>\n          <textarea class=\"form-control\" id=\"fRoleplayExp\" required placeholder=\"اذكر السيرفرات السابقة أو العائلات/العصابات التي كنت منضماً لها ومسؤولياتك السابقة...\"></textarea>\n        </div>\n\n        <h3 style=\"border-bottom: 1px solid var(--brown-border); padding-bottom: 12px; margin-top: 30px; color: var(--amber-light);\">\n          <i class=\"fa-solid fa-shield-halved\"></i> سيناريوهات وقوانين الرول بلاي\n        </h3>\n\n        <div class=\"form-group\">\n          <label>سيناريو الـ FearRP: إذا تم محاصرتك من قبل الشرطة أو عصابة منافسة وكان السلاح موجهاً لرأسك، كيف تتصرف؟ *</label>\n          <textarea class=\"form-control\" id=\"fScenarioFearRP\" required placeholder=\"اشرح بالتفصيل تصرفك طبقاً لقوانين الرول بلاي والـ FearRP...\"></textarea>\n        </div>\n\n        <div class=\"form-group\">\n          <label>لماذا ترغب في الانضمام إلى فانتومز (PHANTOMS) تحديداً؟ وماذا ستضيف للعائلة؟ *</label>\n          <textarea class=\"form-control\" id=\"fReason\" required placeholder=\"ما الذي يجعلك تختار فانتومز عن غيرها؟\"></textarea>\n        </div>\n\n        <div class=\"form-group\">\n          <label>روابط إضافية (كليب شوتينغ / يوتيوب / سيرة ذاتية) <small>(اختياري)</small></label>\n          <input class=\"form-control\" id=\"fExtra\" placeholder=\"https://medal.tv/... أو https://youtube.com/...\">\n        </div>\n\n        <button type=\"submit\" class=\"btn\" id=\"submitAppBtn\" style=\"width: 100%; padding: 14px; font-size: 17px; margin-top: 15px;\">\n          <i class=\"fa-solid fa-paper-plane\"></i> إرسال طلب التقديم\n        </button>\n      </form>\n    </div>\n  </div>\n</section>\n\n<!-- Admin Management Panel Section -->\n<section id=\"panel\">\n  <div class=\"wrap\">\n    <div class=\"sec-hd\">\n      <h2>لوحة <i>التحكم الإدارية</i></h2>\n      <p>إدارة طلبات التقديم، رتب الأعضاء، ومحتوى الموقع</p>\n    </div>\n\n    <!-- Panel Navigation Tabs -->\n    <div class=\"panel-tabs\">\n      <button class=\"tab-btn active\" onclick=\"switchTab('tab-apps')\">\n        <i class=\"fa-solid fa-inbox\"></i> طلبات التقديم <span class=\"user-rank-chip\" id=\"appsCountBadge\">0</span>\n      </button>\n      <button class=\"tab-btn\" onclick=\"switchTab('tab-members')\">\n        <i class=\"fa-solid fa-users\"></i> الأعضاء والرتب\n      </button>\n      <button class=\"tab-btn\" onclick=\"switchTab('tab-creators')\">\n        <i class=\"fa-solid fa-video\"></i> صناع المحتوى\n      </button>\n      <button class=\"tab-btn\" onclick=\"switchTab('tab-rivalries')\">\n        <i class=\"fa-solid fa-skull-crossbones\"></i> سجل العداوات\n      </button>\n      <button class=\"tab-btn\" onclick=\"switchTab('tab-site')\">\n        <i class=\"fa-solid fa-sliders\"></i> نصوص وقوانين الموقع\n      </button>\n      <button class=\"tab-btn\" onclick=\"switchTab('tab-discord')\">\n        <i class=\"fa-brands fa-discord\"></i> ربط الديسكورد والويب هوك\n      </button>\n    </div>\n\n    <!-- Tab 1: Applications Management -->\n    <div class=\"tab-pane active\" id=\"tab-apps\">\n      <div style=\"display: flex; justify-content: space-between; align-items: center; margin-bottom: 20px; flex-wrap: wrap; gap: 10px;\">\n        <div style=\"display: flex; gap: 8px;\">\n          <button class=\"btn sm\" onclick=\"filterApps('all')\">الكل</button>\n          <button class=\"btn sm ghost\" onclick=\"filterApps('pending')\">قيد المراجعة</button>\n          <button class=\"btn sm ghost\" onclick=\"filterApps('accepted')\">المقبولين</button>\n          <button class=\"btn sm ghost\" onclick=\"filterApps('rejected')\">المرفوضين</button>\n        </div>\n        <button class=\"btn sm ghost\" onclick=\"loadApplications()\"><i class=\"fa-solid fa-rotate\"></i> تحديث</button>\n      </div>\n\n      <div id=\"appsReviewList\"></div>\n    </div>\n\n    <!-- Tab 2: Members Management -->\n    <div class=\"tab-pane\" id=\"tab-members\">\n      <div class=\"card\" style=\"margin-bottom: 24px;\">\n        <div style=\"display:flex; justify-content:space-between; align-items:center; margin-bottom:18px; padding-bottom:14px; border-bottom:1px solid var(--brown-border); flex-wrap:wrap; gap:10px;\">\n        <div>\n          <strong style=\"color:var(--amber-light); font-size:16px;\"><i class=\"fa-brands fa-discord\"></i> مزامنة أعضاء الديسكورد التلقائية</strong>\n          <div style=\"font-size:12px; color:var(--tx-muted); margin-top:3px;\">سحب وتحديث كافة الأعضاء الذين يمتلكون رتب العائلة في سيرفر الديسكورد فوراً</div>\n        </div>\n        <button class=\"btn sm\" id=\"btnSyncDiscord\" onclick=\"syncDiscordMembers()\" style=\"background:#5865F2; border-color:#5865F2;\">\n          <i class=\"fa-brands fa-discord\"></i> مزامنة الأعضاء الآن\n        </button>\n      </div>\n      <h3 style=\"margin-top:0; color:var(--amber-light);\"><i class=\"fa-solid fa-user-plus\"></i> إضافة عضو يدوياً</h3>\n        <div class=\"form-grid-2\">\n          <input class=\"form-control\" id=\"newMemberName\" placeholder=\"اسم العضو\">\n          <input class=\"form-control\" id=\"newMemberId\" placeholder=\"Discord ID (اختياري)\">\n        </div>\n        <div class=\"form-grid-2\" style=\"margin-top: 12px;\">\n          <select class=\"form-control\" id=\"newMemberRank\"></select>\n          <button class=\"btn\" onclick=\"addMemberManual()\"><i class=\"fa-solid fa-plus\"></i> إضافة العضو</button>\n        </div>\n      </div>\n\n      <div class=\"card\">\n        <h3 style=\"margin-top:0; color:var(--amber-light);\"><i class=\"fa-solid fa-users\"></i> قائمة أعضاء العائلة</h3>\n        <div id=\"membersAdminList\"></div>\n      </div>\n    </div>\n\n    <!-- Tab 3: Content Creators Management -->\n    <div class=\"tab-pane\" id=\"tab-creators\">\n      <div class=\"card\" style=\"margin-bottom: 24px;\">\n        <h3 style=\"margin-top:0; color:var(--amber-light);\"><i class=\"fa-solid fa-plus\"></i> إضافة صانع محتوى / ستريمر</h3>\n        <div class=\"form-grid-2\">\n          <input class=\"form-control\" id=\"newCrName\" placeholder=\"اسم الستريمر / صانع المحتوى\">\n          <select class=\"form-control\" id=\"newCrPlat\">\n            <option value=\"Twitch\">Twitch</option>\n            <option value=\"YouTube\">YouTube</option>\n            <option value=\"Kick\">Kick</option>\n            <option value=\"TikTok\">TikTok</option>\n          </select>\n        </div>\n        <div class=\"form-grid-2\" style=\"margin-top: 12px;\">\n          <input class=\"form-control\" id=\"newCrUrl\" placeholder=\"رابط القناة (https://twitch.tv/...)\">\n          <input class=\"form-control\" id=\"newCrAvatar\" placeholder=\"رابط صورة الأفتار (اختياري)\">\n        </div>\n        <button class=\"btn\" style=\"margin-top: 14px;\" onclick=\"addCreator()\"><i class=\"fa-solid fa-plus\"></i> إضافة صانع المحتوى</button>\n      </div>\n\n      <div class=\"card\">\n        <h3 style=\"margin-top:0; color:var(--amber-light);\"><i class=\"fa-solid fa-video\"></i> صناع المحتوى المسجلين</h3>\n        <div id=\"creatorsAdminList\"></div>\n      </div>\n    </div>\n\n    <!-- Tab: Rivalries Management -->\n    <div class=\"tab-pane\" id=\"tab-rivalries\">\n      <div class=\"card\" style=\"margin-bottom: 24px;\">\n        <h3 style=\"margin-top:0; color:var(--amber-light);\"><i class=\"fa-solid fa-plus\"></i> إضافة نزاع / عصابة معادية</h3>\n        <div class=\"form-grid-2\">\n          <input class=\"form-control\" id=\"newRivName\" placeholder=\"اسم العصابة المعادية (مثال: كارتل الميديين)\">\n          <select class=\"form-control\" id=\"newRivStatus\">\n            <option value=\"war\">حرب مفتوحة ⚔️ (War)</option>\n            <option value=\"skirmish\">اشتباكات وتوتر ⚠️ (Skirmish)</option>\n            <option value=\"truce\">هدنة مؤقتة 🤝 (Truce)</option>\n            <option value=\"crushed\">تمت التصفية والانكسار 💀 (Crushed)</option>\n          </select>\n        </div>\n        <div class=\"form-grid-2\" style=\"margin-top: 12px;\">\n          <input class=\"form-control\" id=\"newRivLogo\" placeholder=\"رابط لوجو العصابة (اختياري - https://...)\">\n          <input class=\"form-control\" id=\"newRivReason\" placeholder=\"سبب النزاع (مثال: نزاع على شحنة أسلحة)\">\n        </div>\n        <div class=\"form-group\" style=\"margin-top: 12px;\">\n          <input class=\"form-control\" id=\"newRivRules\" placeholder=\"شروط وقواعد الاشتباك (مثال: إطلاق نار مباشر KOS بدون تحذير)\">\n        </div>\n        <button class=\"btn\" onclick=\"addRivalry()\"><i class=\"fa-solid fa-plus\"></i> إضافة إلى سجل العداوات</button>\n      </div>\n\n      <div class=\"card\">\n        <h3 style=\"margin-top:0; color:var(--amber-light);\"><i class=\"fa-solid fa-skull-crossbones\"></i> قائمة العداوات الحالية في السيرفر</h3>\n        <div id=\"rivalriesAdminList\"></div>\n      </div>\n    </div>\n\n    <!-- Tab 4: Site Content & Lore -->\n    <div class=\"tab-pane\" id=\"tab-site\">\n      <div class=\"card\">\n        <h3 style=\"margin-top:0; color:var(--amber-light);\"><i class=\"fa-solid fa-pen-to-square\"></i> نصوص الموقع الأساسية</h3>\n        \n        <div class=\"form-group\">\n          <label>اسم السيرفر</label>\n          <input class=\"form-control\" id=\"inServerName\">\n        </div>\n        \n        <div class=\"form-group\">\n          <label>الشعار (Tagline)</label>\n          <input class=\"form-control\" id=\"inTagline\">\n        </div>\n\n        <div class=\"form-group\">\n          <label>قصة وتاريخ العائلة (About Lore)</label>\n          <textarea class=\"form-control\" id=\"inAbout\" rows=\"5\"></textarea>\n        </div>\n\n        <h4 style=\"color:var(--amber-light); margin: 25px 0 10px;\">قوانين العائلة</h4>\n        <div id=\"rulesEditList\"></div>\n        <button class=\"btn sm ghost\" onclick=\"addRuleField()\" style=\"margin: 10px 0 20px;\"><i class=\"fa-solid fa-plus\"></i> إضافة بند قانون جديد</button>\n\n        <div>\n          <button class=\"btn\" onclick=\"saveSiteContent()\"><i class=\"fa-solid fa-floppy-disk\"></i> حفظ كافة التعديلات</button>\n        </div>\n      </div>\n    </div>\n\n    <!-- Tab 5: Discord & Integrations -->\n    <div class=\"tab-pane\" id=\"tab-discord\">\n      <div class=\"card\">\n        <h3 style=\"margin-top:0; color:var(--amber-light);\"><i class=\"fa-brands fa-discord\"></i> إعدادات ديسكورد والويب هوك</h3>\n        \n        <div class=\"form-group\">\n          <label>رابط دعوة سيرفر الديسكورد (Discord Invite Link)</label>\n          <input class=\"form-control\" id=\"inDcInvite\" value=\"https://discord.gg/5Pa2GNGUS\">\n        </div>\n\n        <div class=\"form-group\">\n          <label>رابط الويب هوك لإرسال التقديمات (Discord Webhook URL)</label>\n          <input class=\"form-control\" id=\"inWebhookUrl\" placeholder=\"https://discord.com/api/webhooks/...\">\n          <small style=\"color:var(--tx-muted); display:block; margin-top:4px;\">\n            كل تقديم جديد أو قرار قبول/رفض سيتم إرساله كإشعار فخم لقناة <b>تقديمات</b> في سيرفر الديسكورد مباشرة!\n          </small>\n        </div>\n\n        <div class=\"form-group\" style=\"margin-top: 16px;\">\n          <label>توكن بوت الديسكورد (Discord Bot Token) - لسحب كل الأعضاء تلقائياً</label>\n          <input type=\"password\" class=\"form-control\" id=\"inBotToken\" placeholder=\"ضع Bot Token هنا لتفعيل مزامنة كافة أعضاء السيرفر بضغطة زر\">\n          <small style=\"color:var(--tx-muted); display:block; margin-top:4px;\">\n            💡 يتيح للبوت سحب كل أعضاء السيرفر الحاصلين على رتب فانتومز تلقائياً بدون الحاجة لتسجيل دخولهم فرداً فرداً. (تأكد من تفعيل Server Members Intent في Discord Developer Portal).\n          </small>\n        </div>\n\n        <div class=\"form-group\" style=\"margin-top: 18px;\">\n          <label style=\"display:flex; align-items:center; gap:10px; cursor:pointer;\">\n            <input type=\"checkbox\" id=\"inAllowApps\" style=\"width:20px; height:20px;\">\n            <span>فتح باب التقديم في العائلة (السماح باستقبال طلبات جديدة)</span>\n          </label>\n        </div>\n\n        <div style=\"margin-top: 24px; display: flex; gap: 12px; flex-wrap: wrap;\">\n          <button class=\"btn\" onclick=\"saveDiscordSettings()\"><i class=\"fa-solid fa-floppy-disk\"></i> حفظ إعدادات الربط</button>\n          <button class=\"btn ghost\" onclick=\"testWebhook()\"><i class=\"fa-solid fa-paper-plane\"></i> إرسال رسالة تجريبية للويب هوك</button>\n        </div>\n      </div>\n    </div>\n\n  </div>\n</section>\n\n<!-- Footer -->\n<footer>\n  <div class=\"wrap\">\n    <div class=\"footer-links\">\n      <a href=\"#about\">عن العائلة</a>\n      <a href=\"#rules\">القوانين</a>\n      <a href=\"#ranks\">الرتب</a>\n      <a href=\"#rivalries\">العداوات والحروب</a>\n      <a href=\"#creators\">صناع المحتوى</a>\n      <a href=\"#apply\">التقديم</a>\n      <a href=\"https://discord.gg/5Pa2GNGUS\" id=\"footerDcLink\" target=\"_blank\">سيرفر الديسكورد</a>\n    </div>\n    <div>© 2026 عائلة فانتومز (𝕻𝖍𝖆𝖓𝖙𝖔𝖒𝖘) · سيرفر كيان رول بلاي [KYN] · كل الحقوق محفوظة</div>\n    <div style=\"color: var(--tx-dim); font-size: 12px; margin-top: 6px;\">غير تابع لشركة Rockstar Games أو Cfx.re</div>\n  </div>\n</footer>\n\n<!-- Decision Modal (Accept / Reject) -->\n<div class=\"modal-overlay\" id=\"decisionModal\">\n  <div class=\"modal-content\">\n    <h3 id=\"decModalTitle\" style=\"margin-top:0;\">قرار بخصوص الطلب</h3>\n    <input type=\"hidden\" id=\"decAppId\">\n    <input type=\"hidden\" id=\"decStatus\">\n\n    <div class=\"form-group\" id=\"decRankGroup\" style=\"display:none;\">\n      <label>تعيين الرتبة في العائلة عند القبول:</label>\n      <select class=\"form-control\" id=\"decAssignRank\"></select>\n    </div>\n\n    <div class=\"form-group\">\n      <label>ملاحظة القرار (تظهر للمتقدم وترسل بالديسكورد):</label>\n      <textarea class=\"form-control\" id=\"decNote\" placeholder=\"اكتب ملاحظة القبول أو سبب الرفض...\"></textarea>\n    </div>\n\n    <div style=\"display:flex; justify-content:flex-end; gap:10px; margin-top:20px;\">\n      <button class=\"btn ghost sm\" onclick=\"closeDecisionModal()\">إلغاء</button>\n      <button class=\"btn sm\" id=\"decConfirmBtn\" onclick=\"confirmDecision()\">تأكيد القرار</button>\n    </div>\n  </div>\n</div>\n\n<!-- Toast -->\n<div id=\"toast\"></div>\n\n<script>\nconst RANKS = [\n  [\"Boss\", \"البوس - قائد العائلة 👑\", \"القيادة العليا وإصدار القرارات المصيرية\"],\n  [\"Co-Boss\", \"نائب البوس 🛡️\", \"إدارة العمليات والنيابة عن القائد\"],\n  [\"Manager\", \"مدير العائلة 📋\", \"التنسيق اللوجستي والإشراف على الموارد\"],\n  [\"Admin\", \"أدمن ومشرف ⚔️\", \"متابعة الانضباط وتوجيه الأعضاء\"],\n  [\"Interview Manager\", \"مسؤول التقديمات 📝\", \"فحص ومقابلة المتقدمين الجدد وإصدار قرارات القبول\"],\n  [\"Golden Member\", \"عضو ذهبي 🥇\", \"عضو مخضرم صاحب كفاءة وتأثير عالي\"],\n  [\"Silver Member\", \"عضو فضي 🥈\", \"عضو متقدم أثبت كفاءته في العمليات\"],\n  [\"Member\", \"فرد معتمد ⚔️\", \"عضو رسمي معتمد في عمليات وحروب العائلة\"],\n  [\"New Phantom\", \"مستجد 👻\", \"عضو جديد تحت الملاحظة والتقييم\"]\n];\n\n\n// نظام المصادقة الشامل وفك البيانات الفوري (دعم ?auth و ?code و ?uid)\n(function initAuth() {\n  try {\n    const p = new URLSearchParams(window.location.search);\n    const a = p.get(\"auth\");\n    const code = p.get(\"code\");\n    const uid = p.get(\"uid\");\n    const name = p.get(\"name\");\n    const rank = p.get(\"rank\");\n    const avatar = p.get(\"avatar\");\n    const err = p.get(\"auth_error\");\n\n    if (err) {\n      setTimeout(() => {\n        showToast(\"تنبيه: \" + (err === \"exchange_failed\" ? \"تعذر تأكيد رمز الدخول من ديسكورد، يرجى المحاولة مرة أخرى.\" : err));\n      }, 500);\n      window.history.replaceState({}, document.title, window.location.pathname);\n    }\n\n    // 1. إذا وصل توكن auth\n    if (a) {\n      try { localStorage.setItem(\"phantoms_auth\", a); } catch(e) {}\n      document.cookie = \"phantoms_auth_tk=\" + encodeURIComponent(a) + \"; path=/; max-age=1209600; SameSite=Lax\";\n      \n      // فك التوكن فورياً\n      try {\n        const parts = a.split(\".\");\n        if (parts.length === 2) {\n          const b64 = parts[0].replace(/-/g, \"+\").replace(/_/g, \"/\");\n          const userObj = JSON.parse(decodeURIComponent(escape(atob(b64))));\n          if (userObj && userObj.id) {\n            ME = userObj;\n            try { localStorage.setItem(\"phantoms_user\", JSON.stringify(userObj)); } catch(e) {}\n          }\n        }\n      } catch(e) {}\n    }\n\n    // 2. إذا وصلت بيانات المستخدم في الرابط مباشرة\n    if (uid && name) {\n      ME = {\n        id: uid,\n        name: decodeURIComponent(name),\n        rank: rank !== null && rank !== undefined ? parseInt(rank, 10) : 8,\n        avatar: avatar ? decodeURIComponent(avatar) : \"\"\n      };\n      try { localStorage.setItem(\"phantoms_user\", JSON.stringify(ME)); } catch(e) {}\n    }\n\n    // 3. إذا وصل كود ديسكورد مباشرة إلى الصفحة الرئيسية (?code=...)\n    if (code) {\n      showToast(\"جاري تأكيد تسجيل الدخول عبر ديسكورد...\");\n      fetch(\"/api/callback?code=\" + encodeURIComponent(code) + \"&format=json\")\n        .then(r => r.json())\n        .then(res => {\n          if (res.success && res.user) {\n            ME = res.user;\n            if (res.token) {\n              try { localStorage.setItem(\"phantoms_auth\", res.token); } catch(e) {}\n              document.cookie = \"phantoms_auth_tk=\" + encodeURIComponent(res.token) + \"; path=/; max-age=1209600; SameSite=Lax\";\n            }\n            try { localStorage.setItem(\"phantoms_user\", JSON.stringify(res.user)); } catch(e) {}\n            renderUser();\n            loadSiteData();\n            showToast(\"مرحباً بك يا \" + esc(res.user.name) + \" في فانتومز!\");\n          } else {\n            showToast(\"فشل استبدال كود ديسكورد\");\n          }\n        })\n        .catch(() => {\n          showToast(\"حدث خطأ أثناء معالجة كود ديسكورد\");\n        });\n    }\n\n    if (a || uid || code) {\n      window.history.replaceState({}, document.title, window.location.pathname);\n    } else {\n      // استرجاع المستخدم المحفوظ مسبقاً من الذاكرة لعدم حدوث وميض\n      try {\n        const cached = localStorage.getItem(\"phantoms_user\");\n        if (cached) ME = JSON.parse(cached);\n      } catch(e) {}\n    }\n  } catch(e) {\n    console.warn(\"Auth init error:\", e);\n  }\n})();\n\nfunction getAuthToken() {\n  try {\n    const t = localStorage.getItem(\"phantoms_auth\");\n    if (t) return t;\n  } catch(e) {}\n  const match = document.cookie.match(/(?:^|; )phantoms_auth_tk=([^;]*)/);\n  return match ? decodeURIComponent(match[1]) : \"\";\n}\n\nfunction getAuthHeaders(extra = {}) {\n  const token = getAuthToken();\n  const headers = Object.assign({}, extra);\n  if (token) headers[\"Authorization\"] = \"Bearer \" + token;\n  return headers;\n}\n\nfunction logoutUser() {\n  try {\n    localStorage.removeItem(\"phantoms_auth\");\n    localStorage.removeItem(\"phantoms_user\");\n  } catch(e) {}\n  document.cookie = \"phantoms_auth_tk=; path=/; max-age=0\";\n  window.location.href = \"/api/logout\";\n}\n\nlet S = {\n  tagline: \"عيلة مش زي أي عيلة. ولاء، قوة، وأسلوب ماشي بخطة تحت قيادة VOLT.\",\n  serverName: \"كيان رول بلاي [KYN]\",\n  discordInvite: \"https://discord.gg/5Pa2GNGUS\",\n  about: \"فانتومز (PHANTOMS) هي إحدى أعرق وأقوى العائلات في سيرفر كيان رول بلاي [KYN]. تأسست العائلة على مبادئ ثابتة: الذكاء والتخطيط والولاء الأخوي قبل السلاح. نتحكم في سيناريوهات المدينة باحترافية وهيبة تُحترم من الجميع، ونسعى دائماً لبناء مجتمع رول بلاي نظيف ومترابط.\",\n  rules: [\n    { title: \"الولاء التام والانضباط\", desc: \"خيانة العائلة أو تسريب أسرار المقرات والمخططات عقوبتها التصفية والطرد النهائي وبلاك ليست.\" },\n    { title: \"احترام التسلسل الإداري\", desc: \"أوامر البوس ونوابه نافذة بدون نقاش، ويجب احترام جميع الإداريين والأعضاء بغض النظر عن الرتبة.\" },\n    { title: \"قواعد الاشتباكات والحروب\", desc: \"ممنوع فتح أي عداوة أو إطلاق رصاص على أي عصابة أو مواطن أو قطاع أمني إلا بإذن صريح من القيادة العليا.\" },\n    { title: \"الالتزام التام بقوانين السيرفر (RP)\", desc: \"ممنوع قطعياً الـ RDM, VDM, FearRP, أو التكلم OOC أثناء السيناريو. الهيبة تُبنى بالرول بلاي النظيف.\" },\n    { title: \"المظهر الموحد وحضور الاجتماعات\", desc: \"الالتزام بلباس العائلة الرسمي وألوان المركبات المعتمدة، والتواجد الإجباري في التجمعات والنداءات الطارئة.\" }\n  ],\n  rivalries: [\n    { id: \"riv-1\", enemyName: \"كارتل الميديين (Medellin Cartel)\", enemyLogo: \"https://raw.githubusercontent.com/walkxcode/dashboard-icons/main/png/skull.png\", status: \"war\", reason: \"نزاع مسلح على مناطق نفوذ السلاح وتجارة الميناء في مدينة كيان\", rules: \"إطلاق نار مباشر (KOS) - حظر دخول مناطق نفوذهم بدون دعم كامل\", startedAt: \"2026-10-15\" },\n    { id: \"riv-2\", enemyName: \"عصابة الفايكنج (Vikings MC)\", enemyLogo: \"https://raw.githubusercontent.com/walkxcode/dashboard-icons/main/png/fivem.png\", status: \"skirmish\", reason: \"محاولات استفزاز متكررة على الدوريات والعمليات الليلية لفانتومز\", rules: \"اشتباكات دفاعية وردع فوري عند التعدي على أفراد العائلة\", startedAt: \"2026-10-20\" }\n  ],\n  creators: [\n    { uid: \"cr-1\", n: \"VOLT Live\", platform: \"Twitch\", url: \"https://twitch.tv/\", avatar: \"\" },\n    { uid: \"cr-2\", n: \"Phantoms Roleplay\", platform: \"YouTube\", url: \"https://youtube.com/\", avatar: \"\" },\n    { uid: \"cr-3\", n: \"Phantoms Kick\", platform: \"Kick\", url: \"https://kick.com/\", avatar: \"\" }\n  ],\n  members: [\n    { uid: \"seed-boss\", n: \"VOLT\", r: 0, avatar: \"\" }\n  ],\n  settings: { allowApplications: true, webhookConfigured: false }\n};\n\nlet ME = null;\nlet APPS = [];\nlet currentFilter = \"all\";\n\nconst $ = id => document.getElementById(id);\nconst esc = s => String(s || \"\").replace(/[&<>\"']/g, c => ({\"&\":\"&amp;\",\"<\":\"&lt;\",\">\":\"&gt;\",'\"':\"&quot;\",\"'\":\"&#39;\"}[c]));\n\nfunction showToast(text) {\n  const t = $(\"toast\");\n  t.textContent = text;\n  t.style.display = \"block\";\n  setTimeout(() => { t.style.display = \"none\"; }, 3500);\n}\n\nconst isStaff = () => ME && ME.rank !== null && ME.rank <= 4;\nconst isHighStaff = () => ME && ME.rank !== null && ME.rank <= 2;\nconst canManageRank = r => isStaff() && (ME.rank === 0 || r > ME.rank);\n\nfunction getRankOpts(selected = 8) {\n  return RANKS.map((r, i) => {\n    const disabled = !canManageRank(i) && i !== selected ? \" disabled\" : \"\";\n    const isSel = i === selected ? \" selected\" : \"\";\n    return `<option value=\"${i}\"${isSel}${disabled}>${r[0]} · ${r[1]}</option>`;\n  }).join(\"\");\n}\n\n// Fetch site data via /api/site\nasync function loadSiteData() {\n  try {\n    const res = await fetch(\"/api/site\", { headers: getAuthHeaders() });\n    if (res.ok) {\n      const data = await res.json();\n      if (data && data.tagline) {\n        S = data;\n        renderSite();\n      }\n    }\n  } catch (e) {\n    console.error(\"Failed to load site data\", e);\n  }\n}\n\n// Fetch user data via /api/me\nasync function loadUser() {\n  try {\n    const res = await fetch(\"/api/me\", { headers: getAuthHeaders() });\n    if (res.ok) {\n      const u = await res.json();\n      if (u && u.id) {\n        ME = u;\n        try { localStorage.setItem(\"phantoms_user\", JSON.stringify(u)); } catch(e) {}\n        renderUser();\n        loadSiteData();\n      } else if (!getAuthToken()) {\n        ME = null;\n        try { localStorage.removeItem(\"phantoms_user\"); } catch(e) {}\n        renderUser();\n      }\n    }\n  } catch (e) {\n    console.error(\"Failed to load user\", e);\n  }\n}\n\n// Render User state\nfunction renderUser() {\n  if (ME) {\n    $(\"loginBtn\").style.display = \"none\";\n    if ($(\"bossQuickBtn\")) $(\"bossQuickBtn\").style.display = \"none\";\n    $(\"userPill\").style.display = \"flex\";\n    $(\"uName\").textContent = ME.name;\n    $(\"uRank\").textContent = ME.rank === null ? \"زائر / متقدم\" : RANKS[ME.rank][0];\n    \n    if (ME.avatar) {\n      $(\"uavWrap\").innerHTML = `<img src=\"${esc(ME.avatar)}\" alt=\"${esc(ME.name)}\">`;\n    } else {\n      $(\"uavWrap\").innerHTML = `<div class=\"default-av\">${esc(ME.name.charAt(0).toUpperCase())}</div>`;\n    }\n\n    $(\"fDiscordTag\").value = ME.name;\n    $(\"fDiscordId\").value = ME.id;\n    $(\"discordLoginPrompt\").style.display = \"none\";\n    $(\"applyForm\").style.display = \"block\";\n\n    if (isStaff()) {\n      $(\"panel\").style.display = \"block\";\n      $(\"panelNavBtn\").style.display = \"inline\";\n      populateStaffPanel();\n    }\n  } else {\n    $(\"loginBtn\").style.display = \"inline-flex\";\n    if ($(\"bossQuickBtn\")) $(\"bossQuickBtn\").style.display = \"inline-flex\";\n    $(\"userPill\").style.display = \"none\";\n    $(\"applyForm\").style.display = \"none\";\n    $(\"discordLoginPrompt\").style.display = \"block\";\n  }\n  checkMyApplication();\n}\n\n// Render Public Site\nfunction renderSite() {\n  $(\"heroTagline\").textContent = S.tagline || \"\";\n  $(\"serverBadge\").textContent = (S.serverName || \"سيرفر كيان رول بلاي [KYN]\") + \" · FiveM\";\n  $(\"aboutContent\").textContent = S.about || \"\";\n  \n  const inv = S.discordInvite || \"https://discord.gg/5Pa2GNGUS\";\n  $(\"dcInviteLink\").href = inv;\n  $(\"footerDcLink\").href = inv;\n\n  // Boss\n  const boss = (S.members || []).find(m => m.r === 0);\n  if (boss) {\n    $(\"bossName\").textContent = boss.n;\n    if (boss.avatar) {\n      $(\"bossAv\").src = boss.avatar;\n    }\n  }\n\n  // Rules\n  const rules = S.rules || [];\n  $(\"rulesGrid\").innerHTML = rules.map((r, i) => `\n    <div class=\"card rule-card\">\n      <div class=\"rule-num\">${i + 1}</div>\n      <div class=\"rule-body\">\n        <h3>${esc(r.title)}</h3>\n        <p>${esc(r.desc)}</p>\n      </div>\n    </div>\n  `).join(\"\");\n\n  // Ranks\n  $(\"ranksGrid\").innerHTML = RANKS.map((r, i) => {\n    const ms = (S.members || []).filter(m => m.r === i);\n    return `\n      <div class=\"card rank-card ${i === 0 ? 'top-rank' : ''}\">\n        <div class=\"rank-hd\">\n          <div class=\"rank-badge\">${i + 1}</div>\n          <div>\n            <h3 class=\"rank-title\">${esc(r[0])}</h3>\n            <div class=\"rank-sub\">${esc(r[1])} · ${ms.length} عضو</div>\n          </div>\n        </div>\n        <p style=\"color:var(--tx-muted); font-size:13px; margin:0 0 10px;\">${esc(r[2])}</p>\n        <div class=\"members-chips\">\n          ${ms.length ? ms.map(m => `\n            <span class=\"member-chip\">\n              ${m.avatar ? `<img src=\"${esc(m.avatar)}\">` : ''}\n              ${esc(m.n)}\n            </span>\n          `).join('') : '<span style=\"color:var(--tx-muted); font-size:13px;\">لا يوجد أعضاء حالياً</span>'}\n        </div>\n      </div>\n    `;\n  }).join(\"\");\n\n  // Rivalries\n  renderRivalries();\n\n  // Creators\n  const creators = S.creators || [];\n  if (creators.length === 0) {\n    $(\"creatorsGrid\").innerHTML = `<div class=\"card\" style=\"grid-column: 1/-1; text-align:center; color:var(--tx-muted);\">لا يوجد صناع محتوى مسجلين حالياً.</div>`;\n  } else {\n    $(\"creatorsGrid\").innerHTML = creators.map(c => {\n      let platClass = \"plat-twitch\";\n      let platIcon = \"fa-twitch\";\n      const p = (c.platform || \"\").toLowerCase();\n      if (p.includes(\"youtube\")) { platClass = \"plat-youtube\"; platIcon = \"fa-youtube\"; }\n      else if (p.includes(\"kick\")) { platClass = \"plat-kick\"; platIcon = \"fa-bolt\"; }\n      else if (p.includes(\"tiktok\")) { platClass = \"plat-tiktok\"; platIcon = \"fa-tiktok\"; }\n\n      return `\n        <div class=\"card creator-card\">\n          ${c.avatar ? `<img class=\"creator-av\" src=\"${esc(c.avatar)}\">` : `<div class=\"default-av creator-av\">${esc(c.n.charAt(0).toUpperCase())}</div>`}\n          <h3 style=\"margin:0 0 4px; font-size:20px;\">${esc(c.n)}</h3>\n          <div><span class=\"creator-plat ${platClass}\"><i class=\"fa-brands ${platIcon}\"></i> ${esc(c.platform)}</span></div>\n          <div style=\"margin-top:16px;\">\n            <a class=\"btn sm\" href=\"${esc(c.url)}\" target=\"_blank\"><i class=\"fa-solid fa-play\"></i> مشاهدة القناة</a>\n          </div>\n        </div>\n      `;\n    }).join(\"\");\n  }\n}\n\n// Check Application status for current user\nasync function checkMyApplication() {\n  if (!ME) return;\n  try {\n    const res = await fetch(\"/api/my-application\");\n    const data = await res.json();\n    const box = $(\"appStatusBox\");\n    if (data.application) {\n      const a = data.application;\n      let badgeClass = \"status-pending\";\n      let statusText = \"قيد المراجعة ⏳\";\n      let statusDesc = \"طلبك قيد الدراسة والمراجعة حالياً من قبل قيادة فانتومز. سيتم الرد عليك قريباً.\";\n\n      if (a.status === \"accepted\") {\n        badgeClass = \"status-accepted\";\n        statusText = \"تم قبولك مبروك! 🎉\";\n        statusDesc = \"تمت الموافقة على طلب انضمامك إلى عائلة فانتومز! يرجى التوجه إلى سيرفر الديسكورد والدخول لروم المقابلات لاستلام رتبتك.\";\n      } else if (a.status === \"rejected\") {\n        badgeClass = \"status-rejected\";\n        statusText = \"تم رفض الطلب ❌\";\n        statusDesc = \"نعتذر منك، لم يتم قبول طلب التقديم حالياً.\";\n      }\n\n      box.style.display = \"block\";\n      box.innerHTML = `\n        <div class=\"app-status-badge ${badgeClass}\">${statusText}</div>\n        <h3 style=\"margin: 0 0 8px;\">حالة تقديمك في عائلة فانتومز</h3>\n        <p style=\"color:var(--tx-muted); max-width:600px; margin: 0 auto 14px;\">${statusDesc}</p>\n        ${a.decisionNote ? `<div style=\"background:rgba(0,0,0,0.3); padding:10px 16px; border-radius:8px; display:inline-block; font-size:14px;\"><b>ملاحظة الإدارة:</b> ${esc(a.decisionNote)}</div>` : ''}\n      `;\n\n      if (a.status === \"pending\" || a.status === \"accepted\") {\n        $(\"appFormBox\").style.display = \"none\";\n      }\n    } else {\n      box.style.display = \"none\";\n      $(\"appFormBox\").style.display = \"block\";\n    }\n  } catch (e) {\n    console.error(e);\n  }\n}\n\n// Submit Application\nasync function submitApplication(e) {\n  e.preventDefault();\n  if (!ME) {\n    showToast(\"يرجى تسجيل الدخول بالديسكورد أولاً\");\n    return;\n  }\n\n  const payload = {\n    realName: $(\"fRealName\").value.trim(),\n    realAge: $(\"fRealAge\").value,\n    charName: $(\"fCharName\").value.trim(),\n    charAge: $(\"fCharAge\").value,\n    hours: $(\"fHours\").value.trim(),\n    specialty: $(\"fSpecialty\").value,\n    roleplayExp: $(\"fRoleplayExp\").value.trim(),\n    scenarioFearRP: $(\"fScenarioFearRP\").value.trim(),\n    reason: $(\"fReason\").value.trim(),\n    extra: $(\"fExtra\").value.trim()\n  };\n\n  $(\"submitAppBtn\").disabled = true;\n  $(\"submitAppBtn\").innerHTML = '<i class=\"fa-solid fa-spinner fa-spin\"></i> جاري الإرسال...';\n\n  try {\n    const res = await fetch(\"/api/apply\", {\n      method: \"POST\",\n      headers: getAuthHeaders({ \"Content-Type\": \"application/json\" }),\n      body: JSON.stringify(payload)\n    });\n    const result = await res.json();\n    if (res.ok) {\n      showToast(result.message || \"تم إرسال طلب التقديم بنجاح!\");\n      checkMyApplication();\n    } else {\n      showToast(result.error || \"فشل إرسال الطلب\");\n    }\n  } catch (err) {\n    showToast(\"خطأ في الاتصال بالخادم\");\n  } finally {\n    $(\"submitAppBtn\").disabled = false;\n    $(\"submitAppBtn\").innerHTML = '<i class=\"fa-solid fa-paper-plane\"></i> إرسال طلب التقديم';\n  }\n}\n\n// ----------------- Staff Admin Panel Functions -----------------\nfunction switchTab(tabId) {\n  document.querySelectorAll(\".tab-btn\").forEach(b => b.classList.remove(\"active\"));\n  document.querySelectorAll(\".tab-pane\").forEach(p => p.classList.remove(\"active\"));\n  event.currentTarget.classList.add(\"active\");\n  $(tabId).classList.add(\"active\");\n}\n\nfunction populateStaffPanel() {\n  loadApplications();\n  renderMembersAdmin();\n  renderCreatorsAdmin();\n  renderRivalriesAdmin();\n  if ($(\"inBotToken\")) $(\"inBotToken\").value = S.settings?.botToken || \"\";\n  \n  $(\"inServerName\").value = S.serverName || \"\";\n  $(\"inTagline\").value = S.tagline || \"\";\n  $(\"inAbout\").value = S.about || \"\";\n  $(\"inDcInvite\").value = S.discordInvite || \"https://discord.gg/5Pa2GNGUS\";\n  $(\"inAllowApps\").checked = S.settings?.allowApplications !== false;\n  $(\"newMemberRank\").innerHTML = getRankOpts(4);\n\n  renderRulesEditor();\n}\n\nasync function loadApplications() {\n  if (!isStaff()) return;\n  try {\n    const res = await fetch(\"/api/applications\", { headers: getAuthHeaders() });\n    if (res.ok) {\n      const data = await res.json();\n      APPS = data.applications || [];\n      const pendingCount = APPS.filter(a => a.status === \"pending\").length;\n      $(\"appsCountBadge\").textContent = pendingCount;\n      renderAppsList();\n    }\n  } catch (e) {\n    console.error(e);\n  }\n}\n\nfunction filterApps(status) {\n  currentFilter = status;\n  renderAppsList();\n}\n\nfunction renderAppsList() {\n  const container = $(\"appsReviewList\");\n  let filtered = APPS;\n  if (currentFilter !== \"all\") {\n    filtered = APPS.filter(a => a.status === currentFilter);\n  }\n\n  if (filtered.length === 0) {\n    container.innerHTML = `<div class=\"card\" style=\"text-align:center; color:var(--tx-muted);\">لا توجد طلبات تقديم في هذا القسم.</div>`;\n    return;\n  }\n\n  container.innerHTML = filtered.map(a => {\n    let statusBadge = '<span class=\"app-status-badge status-pending\">قيد المراجعة</span>';\n    if (a.status === \"accepted\") statusBadge = '<span class=\"app-status-badge status-accepted\">مقبول</span>';\n    if (a.status === \"rejected\") statusBadge = '<span class=\"app-status-badge status-rejected\">مرفوض</span>';\n\n    return `\n      <div class=\"review-item ${a.status}\">\n        <div class=\"review-hd\">\n          <div style=\"display:flex; align-items:center; gap:12px;\">\n            ${a.avatar ? `<img src=\"${esc(a.avatar)}\" style=\"width:40px; height:40px; border-radius:50%;\">` : ''}\n            <div>\n              <b style=\"font-size:17px;\">${esc(a.charName)} <small style=\"color:var(--tx-muted);\">(${esc(a.discordTag)})</small></b>\n              <div style=\"font-size:12px; color:var(--tx-muted);\">تاريخ التقديم: ${new Date(a.createdAt).toLocaleString('ar-EG')}</div>\n            </div>\n          </div>\n          <div>${statusBadge}</div>\n        </div>\n\n        <div class=\"review-meta\">\n          <div><b>الاسم الواقعي:</b> ${esc(a.realName)} (${a.realAge} سنة)</div>\n          <div><b>عمر الشخصية:</b> ${a.charAge} سنة</div>\n          <div><b>ساعات FiveM:</b> ${esc(a.hours)}</div>\n          <div><b>التخصص:</b> <span style=\"color:var(--amber-light);\">${esc(a.specialty)}</span></div>\n          <div><b>Discord ID:</b> <code>${esc(a.userId)}</code></div>\n        </div>\n\n        <div class=\"review-answer\">\n          <b>الخبرات السابقة في الرول بلاي والعصابات:</b>\n          ${esc(a.roleplayExp)}\n        </div>\n\n        <div class=\"review-answer\">\n          <b>إجابة سيناريو الحصار والـ FearRP:</b>\n          ${esc(a.scenarioFearRP)}\n        </div>\n\n        <div class=\"review-answer\">\n          <b>سبب اختيار فانتومز:</b>\n          ${esc(a.reason)}\n        </div>\n\n        ${a.extra ? `\n          <div class=\"review-answer\">\n            <b>روابط وكليبات إضافية:</b>\n            <a href=\"${esc(a.extra)}\" target=\"_blank\" style=\"color:var(--amber-light); text-decoration:underline;\">${esc(a.extra)}</a>\n          </div>\n        ` : ''}\n\n        ${a.decisionNote ? `\n          <div style=\"background:rgba(217,146,67,0.1); border:1px solid var(--brown-border-light); padding:8px 12px; border-radius:8px; font-size:13px; margin-top:8px;\">\n            <b>قرار الإدارة:</b> ${esc(a.decisionNote)} (${esc(a.decisionBy || '')})\n          </div>\n        ` : ''}\n\n        <div class=\"review-actions\">\n          ${a.status !== \"accepted\" ? `\n            <button class=\"btn sm\" onclick=\"openDecision('${a.id}', 'accepted')\"><i class=\"fa-solid fa-check\"></i> قبول الطلب</button>\n          ` : ''}\n          ${a.status !== \"rejected\" ? `\n            <button class=\"btn sm ghost\" onclick=\"openDecision('${a.id}', 'rejected')\"><i class=\"fa-solid fa-xmark\"></i> رفض الطلب</button>\n          ` : ''}\n          <button class=\"btn sm del\" onclick=\"deleteApplication('${a.id}')\"><i class=\"fa-solid fa-trash\"></i> حذف</button>\n        </div>\n      </div>\n    `;\n  }).join(\"\");\n}\n\n// Open Decision Modal\nfunction openDecision(appId, status) {\n  $(\"decAppId\").value = appId;\n  $(\"decStatus\").value = status;\n  $(\"decNote\").value = \"\";\n\n  if (status === \"accepted\") {\n    $(\"decModalTitle\").innerHTML = '<i class=\"fa-solid fa-user-check\" style=\"color:var(--green)\"></i> قبول طلب التقديم';\n    $(\"decRankGroup\").style.display = \"block\";\n    $(\"decAssignRank\").innerHTML = getRankOpts(4);\n    $(\"decConfirmBtn\").className = \"btn sm\";\n    $(\"decConfirmBtn\").textContent = \"تأكيد القبول وإرسال الإشعار\";\n  } else {\n    $(\"decModalTitle\").innerHTML = '<i class=\"fa-solid fa-user-xmark\" style=\"color:var(--red)\"></i> رفض طلب التقديم';\n    $(\"decRankGroup\").style.display = \"none\";\n    $(\"decConfirmBtn\").className = \"btn sm del\";\n    $(\"decConfirmBtn\").textContent = \"تأكيد الرفض وإرسال الإشعار\";\n  }\n\n  $(\"decisionModal\").classList.add(\"active\");\n}\n\nfunction closeDecisionModal() {\n  $(\"decisionModal\").classList.remove(\"active\");\n}\n\nasync function confirmDecision() {\n  const id = $(\"decAppId\").value;\n  const status = $(\"decStatus\").value;\n  const note = $(\"decNote\").value.trim();\n  const assignRank = status === \"accepted\" ? $(\"decAssignRank\").value : undefined;\n\n  try {\n    const res = await fetch(`/api/applications/${id}`, {\n      method: \"PATCH\",\n      headers: { \"Content-Type\": \"application/json\" },\n      body: JSON.stringify({ status, note, assignRank })\n    });\n    if (res.ok) {\n      showToast(\"تم تحديث حالة الطلب وإرسال التنبيه!\");\n      closeDecisionModal();\n      loadApplications();\n      loadSiteData();\n    } else {\n      const err = await res.json();\n      showToast(err.error || \"فشل تنفيذ القرار\");\n    }\n  } catch (e) {\n    showToast(\"خطأ في الاتصال\");\n  }\n}\n\nasync function deleteApplication(id) {\n  if (!confirm(\"هل أنت متأكد من حذف هذا الطلب نهائياً؟\")) return;\n  try {\n    const res = await fetch(`/api/applications/${id}`, { method: \"DELETE\" });\n    if (res.ok) {\n      showToast(\"تم حذف الطلب\");\n      loadApplications();\n    }\n  } catch (e) {\n    showToast(\"خطأ في الحذف\");\n  }\n}\n\n// Members Management in Admin\nfunction renderMembersAdmin() {\n  const list = $(\"membersAdminList\");\n  list.innerHTML = (S.members || []).map(m => `\n    <div style=\"display:flex; justify-content:space-between; align-items:center; padding:10px 0; border-bottom:1px solid var(--brown-border); flex-wrap:wrap; gap:10px;\">\n      <div style=\"display:flex; align-items:center; gap:10px;\">\n        ${m.avatar ? `<img src=\"${esc(m.avatar)}\" style=\"width:32px; height:32px; border-radius:50%;\">` : '<div class=\"default-av\" style=\"width:32px; height:32px; font-size:12px;\">'+esc(m.n.charAt(0))+'</div>'}\n        <div>\n          <b>${esc(m.n)}</b>\n          <div style=\"font-size:12px; color:var(--tx-muted);\">${esc(m.id || \"بدون ديسكورد\")}</div>\n        </div>\n      </div>\n      <div style=\"display:flex; align-items:center; gap:8px;\">\n        ${canManageRank(m.r) ? `\n          <select class=\"form-control\" style=\"width:auto; padding:4px 8px; font-size:13px;\" onchange=\"updateMemberRank('${m.uid}', this.value)\">\n            ${getRankOpts(m.r)}\n          </select>\n          <button class=\"btn sm del\" onclick=\"removeMember('${m.uid}')\"><i class=\"fa-solid fa-trash\"></i></button>\n        ` : `<span class=\"user-rank-chip\">${RANKS[m.r][0]}</span>`}\n      </div>\n    </div>\n  `).join(\"\");\n}\n\nasync function addMemberManual() {\n  const n = $(\"newMemberName\").value.trim();\n  const id = $(\"newMemberId\").value.trim();\n  const r = parseInt($(\"newMemberRank\").value, 10);\n  if (!n) { showToast(\"الاسم مطلوب\"); return; }\n\n  try {\n    const res = await fetch(\"/api/members\", {\n      method: \"POST\",\n      headers: { \"Content-Type\": \"application/json\" },\n      body: JSON.stringify({ n, id, r })\n    });\n    if (res.ok) {\n      showToast(\"تمت إضافة العضو بنجاح\");\n      $(\"newMemberName\").value = \"\";\n      $(\"newMemberId\").value = \"\";\n      loadSiteData();\n    } else {\n      const j = await res.json();\n      showToast(j.error || \"خطأ في الإضافة\");\n    }\n  } catch (e) {\n    showToast(\"خطأ في الاتصال\");\n  }\n}\n\nasync function updateMemberRank(uid, r) {\n  try {\n    const res = await fetch(`/api/members/${uid}`, {\n      method: \"PATCH\",\n      headers: { \"Content-Type\": \"application/json\" },\n      body: JSON.stringify({ r: parseInt(r, 10) })\n    });\n    if (res.ok) {\n      showToast(\"تم تحديث رتبة العضو\");\n      loadSiteData();\n    }\n  } catch (e) {\n    showToast(\"خطأ في التحديث\");\n  }\n}\n\nasync function removeMember(uid) {\n  if (!confirm(\"هل أنت متأكد من حذف العضو من قائمة العائلة؟\")) return;\n  try {\n    const res = await fetch(`/api/members/${uid}`, { method: \"DELETE\" });\n    if (res.ok) {\n      showToast(\"تم حذف العضو\");\n      loadSiteData();\n    }\n  } catch (e) {\n    showToast(\"خطأ في الحذف\");\n  }\n}\n\n// Creators Management in Admin\nfunction renderCreatorsAdmin() {\n  const list = $(\"creatorsAdminList\");\n  list.innerHTML = (S.creators || []).map(c => `\n    <div style=\"display:flex; justify-content:space-between; align-items:center; padding:10px 0; border-bottom:1px solid var(--brown-border); flex-wrap:wrap; gap:10px;\">\n      <div>\n        <b>${esc(c.n)}</b> (${esc(c.platform)})\n        <div style=\"font-size:12px; color:var(--tx-muted);\">${esc(c.url)}</div>\n      </div>\n      <div>\n        <button class=\"btn sm del\" onclick=\"removeCreator('${c.uid}')\"><i class=\"fa-solid fa-trash\"></i> حذف</button>\n      </div>\n    </div>\n  `).join(\"\");\n}\n\nasync function addCreator() {\n  const n = $(\"newCrName\").value.trim();\n  const platform = $(\"newCrPlat\").value;\n  const url = $(\"newCrUrl\").value.trim();\n  const avatar = $(\"newCrAvatar\").value.trim();\n  if (!n) { showToast(\"الاسم مطلوب\"); return; }\n\n  try {\n    const res = await fetch(\"/api/creators\", {\n      method: \"POST\",\n      headers: { \"Content-Type\": \"application/json\" },\n      body: JSON.stringify({ n, platform, url, avatar })\n    });\n    if (res.ok) {\n      showToast(\"تمت إضافة صانع المحتوى بنجاح\");\n      $(\"newCrName\").value = \"\";\n      $(\"newCrUrl\").value = \"\";\n      $(\"newCrAvatar\").value = \"\";\n      loadSiteData();\n    }\n  } catch (e) {\n    showToast(\"خطأ في الاتصال\");\n  }\n}\n\nasync function removeCreator(uid) {\n  if (!confirm(\"متأكد من حذف صانع المحتوى؟\")) return;\n  try {\n    const res = await fetch(`/api/creators/${uid}`, { method: \"DELETE\" });\n    if (res.ok) {\n      showToast(\"تم حذف صانع المحتوى\");\n      loadSiteData();\n    }\n  } catch (e) {\n    showToast(\"خطأ في الحذف\");\n  }\n}\n\n// Rules Editor in Admin\nfunction renderRulesEditor() {\n  const list = $(\"rulesEditList\");\n  list.innerHTML = (S.rules || []).map((r, i) => `\n    <div style=\"background:rgba(0,0,0,0.25); border:1px solid var(--brown-border); border-radius:10px; padding:14px; margin-bottom:12px;\">\n      <div style=\"display:flex; justify-content:space-between; align-items:center; margin-bottom:8px;\">\n        <span style=\"font-weight:700; color:var(--amber);\">البند #${i + 1}</span>\n        <button class=\"btn sm del\" type=\"button\" onclick=\"deleteRuleField(${i})\"><i class=\"fa-solid fa-trash\"></i></button>\n      </div>\n      <input class=\"form-control rule-in-title\" style=\"margin-bottom:8px;\" value=\"${esc(r.title)}\" placeholder=\"عنوان القانون\">\n      <textarea class=\"form-control rule-in-desc\" rows=\"2\" placeholder=\"تفاصيل وشرح القانون\">${esc(r.desc)}</textarea>\n    </div>\n  `).join(\"\");\n}\n\nfunction addRuleField() {\n  if (!S.rules) S.rules = [];\n  S.rules.push({ title: \"قانون جديد\", desc: \"اكتب وصف القانون هنا...\" });\n  renderRulesEditor();\n}\n\nfunction deleteRuleField(idx) {\n  S.rules.splice(idx, 1);\n  renderRulesEditor();\n}\n\nasync function saveSiteContent() {\n  const titles = document.querySelectorAll(\".rule-in-title\");\n  const descs = document.querySelectorAll(\".rule-in-desc\");\n  const rules = [];\n  titles.forEach((t, i) => {\n    rules.push({ title: t.value.trim(), desc: descs[i].value.trim() });\n  });\n\n  const payload = {\n    serverName: $(\"inServerName\").value.trim(),\n    tagline: $(\"inTagline\").value.trim(),\n    about: $(\"inAbout\").value.trim(),\n    rules\n  };\n\n  try {\n    const res = await fetch(\"/api/site\", {\n      method: \"POST\",\n      headers: { \"Content-Type\": \"application/json\" },\n      body: JSON.stringify(payload)\n    });\n    if (res.ok) {\n      showToast(\"تم حفظ محتوى وقوانين الموقع بنجاح!\");\n      loadSiteData();\n    } else {\n      showToast(\"حدث خطأ في حفظ المحتوى\");\n    }\n  } catch (e) {\n    showToast(\"خطأ في الاتصال\");\n  }\n}\n\nasync function saveDiscordSettings() {\n  const payload = {\n    discordInvite: $(\"inDcInvite\").value.trim(),\n    webhookUrl: $(\"inWebhookUrl\").value.trim(),\n    botToken: $(\"inBotToken\") ? $(\"inBotToken\").value.trim() : undefined,\n    allowApplications: $(\"inAllowApps\").checked\n  };\n\n  try {\n    const res = await fetch(\"/api/site\", {\n      method: \"POST\",\n      headers: { \"Content-Type\": \"application/json\" },\n      body: JSON.stringify(payload)\n    });\n    if (res.ok) {\n      showToast(\"تم حفظ إعدادات ديسكورد والويب هوك بنجاح!\");\n      loadSiteData();\n    } else {\n      showToast(\"خطأ في الاتصال\");\n    }\n  } catch (e) {\n    showToast(\"خطأ في الاتصال\");\n  }\n}\n\nasync function testWebhook() {\n  const url = $(\"inWebhookUrl\").value.trim();\n  if (!url) {\n    showToast(\"يرجى وضع رابط الويب هوك أولاً لتجربته\");\n    return;\n  }\n  showToast(\"جاري إرسال رسالة تجريبية للديسكورد...\");\n  try {\n    await fetch(url, {\n      method: \"POST\",\n      headers: { \"Content-Type\": \"application/json\" },\n      body: JSON.stringify({\n        username: \"نظام فانتومز\",\n        avatar_url: \"https://cdn.discordapp.com/icons/1525115353003327578/160270721afdfc2b180499e5469288a6.png\",\n        embeds: [{\n          title: \"🦅 تجربة ربط الويب هوك ناجحة!\",\n          description: \"تم ربط موقع عائلة فانتومز بسيرفر الديسكورد بنجاح! سيتم إرسال كافة التقديمات الجديدة هنا.\",\n          color: 0xc98a4b,\n          timestamp: new Date().toISOString()\n        }]\n      })\n    });\n    showToast(\"تم إرسال رسالة التجربة إلى الديسكورد بنجاح!\");\n  } catch (e) {\n    showToast(\"فشل إرسال التجربة، تحقق من صحة الرابط\");\n  }\n}\n\n// Initial Boot\n(async () => {\n  if (ME) renderUser();\n  renderSite();\n  await loadSiteData();\n  await loadUser();\n})();\n</script>\n</body>\n</html>\n";
